.billing_details .checked-box input[type="checkbox"]+label span {
    position: absolute;
    top: 2px;
    left: 0;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    vertical-align: middle;
    background-color: transparent;
    background: var(--finris-base);
    cursor: pointer;
    -webkit-transition: all 300ms ease;
