    position: relative;
    display: flex;
    align-items: center;
}

.account__form-btn {
    border: none;
}

.account__form-btn-box .checked-box {
    position: relative;
    display: block;
    margin-left: 20px;
}

.account__form-btn-box .checked-box label {
    position: relative;
    display: inline-block;
    padding-left: 30px;
    margin-right: 0px;
    margin-bottom: 0;
    color: var(--finris-gray);
    font-size: 16px;
    line-height: 22px;
    font-weight: 500;
    text-transform: none;
    cursor: pointer;
    font-family: var(--finris-font);
}

.account__form-btn-box .checked-box input[type="checkbox"] {
    display: none;
}

.account__form-btn-box .checked-box input[type="checkbox"]+label span {
    position: absolute;
    top: 2px;
    left: 0;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    vertical-align: middle;
    background: var(--finris-white);
    cursor: pointer;
    -webkit-transition: all 300ms ease;
    -moz-transition: all 300ms ease;
    -ms-transition: all 300ms ease;
    -o-transition: all 300ms ease;
    transition: all 300ms ease;
    border: 2px solid #dddddd;
}

