    border: 1px solid #c8daf5;
    background: #fff;
    color: #173f7f;
    font-weight: 700;
    box-shadow: none;
}

.meeting-scheduler__step-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: flex-end;
}

.meeting-scheduler__review {
    border: 1px solid #d7e6fb;
    border-radius: 12px;
    background: linear-gradient(180deg, #ffffff 0%, #f6faff 100%);
    padding: 14px;
    margin-bottom: 14px;
}

.meeting-scheduler__review h4 {
    margin: 0 0 10px;
    font-size: 20px;
    color: #103975;
}

.meeting-scheduler__review-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.meeting-scheduler__review-grid div {
    border: 1px solid #dce8fb;
    border-radius: 10px;
    background: #fff;
    padding: 9px 10px;
}

.meeting-scheduler__review-grid span {
    display: block;
    font-size: 11px;
    color: #6680a6;
    text-transform: uppercase;
    letter-spacing: .04em;
}

.meeting-scheduler__review-grid strong {
    color: #123b76;
    font-size: 14px;
    line-height: 1.4;
}

.meeting-scheduler__review-note {
    margin: 10px 0 0;
    font-size: 13px;
    color: #426287;
}

.meeting-scheduler__next-box {
    margin-top: 12px;
    border: 1px solid #d9e8fc;
    border-radius: 12px;
    background: linear-gradient(180deg, #ffffff 0%, #f5f9ff 100%);
    padding: 12px 14px;
}

.meeting-scheduler__next-box h4 {
    margin: 0 0 8px;
    font-size: 18px;
    color: #103975;
}

.meeting-scheduler__next-box ul {
    display: grid;
    gap: 6px;
    margin: 0;
}

.meeting-scheduler__next-box li {
    color: #2f4e78;
    font-size: 14px;
    display: flex;
    align-items: flex-start;
    gap: 8px;
}

.meeting-scheduler__next-box li .icon-check {
    margin-top: 4px;
    color: #1b8de4;
}

.meeting-ghost-btn {
    background: #fff !important;
    color: #133d7b !important;
    border: 1px solid #c9dbf6 !important;
    box-shadow: none !important;
}

.meeting-ghost-btn::before,
.meeting-ghost-btn::after {
    display: none !important;
}

.meeting-ghost-btn:hover,
.meeting-ghost-btn:focus {
    background: #f3f8ff !important;
    color: #0f3f84 !important;
    border-color: #a9c8f0 !important;
}

.meeting-scheduler__calendar-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 12px;
}

.meeting-scheduler__calendar-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--finris-bdr-color);
    border-radius: 30px;
    padding: 8px 14px;
    font-size: 13px;
    font-weight: 600;
    color: var(--finris-black);
    background: #fff;
}

.meeting-scheduler__calendar-link:hover {
    border-color: var(--finris-base);
    color: var(--finris-base);
}

.meeting-scheduler__calendar-link[aria-disabled="true"] {
    opacity: 0.6;
    pointer-events: none;
}

.meeting-calendar {
    margin-top: 20px;
    border: 1px solid var(--finris-bdr-color);
    border-radius: 16px;
    background: #fff;
    padding: 16px;
}

.meeting-calendar__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
}

.meeting-calendar__month {
    margin: 0;
    font-size: 17px;
}

.meeting-calendar__nav {
    width: 34px;
    height: 34px;
    border: 1px solid var(--finris-bdr-color);
    border-radius: 50%;
    background: #fff;
    font-size: 20px;
    line-height: 1;
    color: var(--finris-black);
}

.meeting-calendar__weekdays,
.meeting-calendar__grid {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 6px;
}

.meeting-calendar__weekdays {
    margin-bottom: 6px;
}

.meeting-calendar__weekdays span {
    text-align: center;
    font-size: 11px;
    font-weight: 700;
    color: var(--finris-gray);
    text-transform: uppercase;
}

.meeting-calendar__day {
    height: 34px;
    border-radius: 8px;
    border: 1px solid transparent;
    background: #f6f9ff;
    font-size: 13px;
    color: var(--finris-black);
}

.meeting-calendar__day.is-booked {
    background: #ffecec;
    color: #b44747;
}

.meeting-calendar__day.is-past {
    background: #f2f4f8;
    color: #9aa6bb;
}

.meeting-calendar__day.is-selected {
    background: #0f63b8;
    color: #fff;
}

.meeting-calendar__day.is-empty {
    background: transparent;
    border-color: transparent;
}

.meeting-calendar__legend {
    margin-top: 10px;
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    font-size: 12px;
    color: var(--finris-gray);
}

.meeting-calendar__legend i {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    display: inline-block;
    margin-right: 6px;
}

.meeting-calendar__legend i.is-available {
    background: #dbeafe;
}

.meeting-calendar__legend i.is-booked {
    background: #fecaca;
}

.meeting-calendar__legend i.is-selected {
    background: var(--finris-base);
}

@media (max-width: 1199px) {
    .meeting-scheduler {
        padding: 76px 0;
    }

    .meeting-scheduler__content {
        padding-right: 0;
        margin-bottom: 26px;
    }
}

@media (max-width: 767px) {
    .meeting-scheduler {
        padding: 60px 0;
    }

    .meeting-scheduler__inner {
        padding: 22px;
    }

    .meeting-scheduler__form-box {
        padding: 18px;
    }

    .meeting-scheduler__steps {
        grid-template-columns: 1fr;
    }

    .meeting-scheduler__quick-date {
        width: 100%;
        justify-content: space-between;
    }

    .meeting-scheduler__review-grid {
        grid-template-columns: 1fr;
    }

    .meeting-scheduler__step-actions {
        justify-content: stretch;
    }

    .meeting-scheduler__step-actions .meeting-scheduler__btn {
        width: 100%;
    }
}

/*--------------------------------------------------------------
# Quick Path
--------------------------------------------------------------*/
.quick-path {
    position: relative;
    display: block;
    padding: 0 0 88px;
}

.quick-path__inner {
    position: relative;
    overflow: hidden;
    border: 1px solid #dbe7ff;
    border-radius: 22px;
    background: linear-gradient(145deg, #f8fbff 0%, #eef5ff 100%);
    padding: 38px;
}

.quick-path__inner::before {
    content: "";
    position: absolute;
    right: -90px;
    top: -90px;
    width: 230px;
    height: 230px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(36, 129, 255, 0.24) 0%, rgba(36, 129, 255, 0) 72%);
    pointer-events: none;
}

.quick-path__card {
    position: relative;
    z-index: 1;
    height: 100%;
    border: 1px solid rgba(24, 85, 170, 0.16);
    border-radius: 16px;
    background: linear-gradient(180deg, #ffffff 0%, #f9fcff 100%);
    padding: 20px;
    box-shadow: 0 12px 28px rgba(17, 61, 126, 0.08);
    transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}

.quick-path__card:hover {
    transform: translateY(-6px);
    border-color: rgba(24, 85, 170, 0.35);
    box-shadow: 0 16px 34px rgba(17, 61, 126, 0.15);
}

.quick-path__art {
    margin: -2px -2px 14px;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid rgba(31, 127, 217, 0.14);
}

.quick-path__art img {
    width: 100%;
    height: 118px;
    object-fit: cover;
    display: block;
}

.quick-path__card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
}

.quick-path__step {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 72px;
    height: 30px;
    border-radius: 999px;
    background: #e9f2ff;
    color: #1b4e96;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.quick-path__eta {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 80px;
    height: 30px;
    border-radius: 999px;
    background: #12356b;
    color: #fff;
    font-size: 12px;
    font-weight: 700;
}

.quick-path__card h3 {
    margin: 0 0 10px;
    font-size: 27px;
    line-height: 1.3;
}

.quick-path__card p {
    margin: 0;
    min-height: 82px;
    color: #4f6483;
}

.quick-path__link {
    margin-top: 16px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 46px;
    padding: 0 20px;
    border-radius: 999px;
    border: 1px solid rgba(35, 132, 255, 0.18);
    background: linear-gradient(135deg, #1f7fd9 0%, #278fe9 100%);
    color: #fff;
    box-shadow: 0 10px 20px rgba(35, 132, 255, 0.28);
    font-weight: 700;
}

.quick-path__link:hover {
    color: #fff;
    background: linear-gradient(135deg, #156dc4 0%, #1d85e0 100%);
}

/*--------------------------------------------------------------
# Trust Pillars
--------------------------------------------------------------*/
.trust-pillars {
    position: relative;
    display: block;
    padding: 12px 0 0;
}

.trust-pillars__inner {
    background: linear-gradient(120deg, #0f2f64 0%, #1d5fb6 100%);
    border-radius: 16px;
    padding: 20px;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
}

.trust-pillars__item {
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 12px;
    padding: 14px;
}

.trust-pillars__item h3 {
    color: #fff;
    margin: 0 0 6px;
    font-size: 19px;
}

.trust-pillars__item p {
    color: rgba(255, 255, 255, 0.9);
    margin: 0;
    font-size: 14px;
    line-height: 1.45;
}

/*--------------------------------------------------------------
# Quick Quote Widget
--------------------------------------------------------------*/
.quick-quote-widget {
    position: relative;
    display: block;
    padding: 0 0 86px;
}

.quick-quote-widget__inner {
    border: 1px solid #d8e6fc;
    border-radius: 20px;
    background: linear-gradient(180deg, #ffffff 0%, #f4f8ff 100%);
    padding: 28px;
    box-shadow: 0 16px 30px rgba(16, 57, 117, 0.10);
}

.quick-quote-widget__tag {
    display: inline-flex;
    align-items: center;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 700;
    color: #0f4e9b;
    background: rgba(32, 129, 219, 0.12);
    padding: 7px 12px;
    margin-bottom: 10px;
}

.quick-quote-widget__head h2 {
    margin: 0 0 8px;
    font-size: 34px;
    line-height: 1.2;
}

.quick-quote-widget__head p {
    margin: 0;
}

.quick-quote-widget__form {
    margin-top: 18px;
}

.quick-quote-widget__grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
}

.quick-quote-widget__field label {
    display: block;
    font-size: 13px;
    font-weight: 700;
    color: #19437f;
    margin-bottom: 7px;
}

.quick-quote-widget__field select {
    width: 100%;
    height: 48px;
    border: 1px solid #cfe0fb;
    border-radius: 10px;
    background: #fff;
    padding: 0 12px;
    color: #163c72;
}

.quick-quote-widget__result {
    margin-top: 14px;
    border: 1px solid #d3e4fb;
    border-radius: 14px;
    background: #fff;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    padding: 12px;
    align-items: center;
}

.quick-quote-widget__result span {
    display: block;
    font-size: 12px;
    color: #607493;
    font-weight: 600;
}

.quick-quote-widget__result strong {
    display: block;
    font-size: 16px;
    color: #103975;
    line-height: 1.25;
}

.quick-quote-widget__cta {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 42px;
    border-radius: 999px;
    background: linear-gradient(135deg, #1f63ba 0%, #2081db 100%);
    color: #fff;
    font-size: 14px;
    font-weight: 700;
    padding: 10px 18px;
}

.quick-quote-widget__cta:hover {
    color: #fff;
}

/*--------------------------------------------------------------
# FAQ Intent Chips
--------------------------------------------------------------*/
.faq-intent {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 0 0 16px;
}

.faq-intent__chip {
    border: 1px solid #cfe0fb;
    border-radius: 999px;
    background: #fff;
    color: #173f78;
    font-size: 13px;
    font-weight: 700;
    padding: 8px 14px;
    transition: all 0.22s ease;
}

.faq-intent__chip.is-active {
    color: #fff;
    border-color: transparent;
    background: linear-gradient(135deg, #194f97 0%, #2081db 100%);
}

.faq-one__right .accrodion-grp[data-faq-panel] {
    display: none;
}

.faq-one__right .accrodion-grp[data-faq-panel].is-active {
    display: block;
}

/* Home FAQ alignment tuning */
.faq-one--home .faq-one__left {
    margin-right: 48px;
}

.faq-one--home .faq-one__right {
    margin-right: 0;
}

.faq-one--home {
    padding: 78px 0 62px;
}

/*--------------------------------------------------------------
# CTA Trust Badges
--------------------------------------------------------------*/
.cta-trust-badges {
    margin: 14px 0 0;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.cta-trust-badges span {
    display: inline-flex;
    align-items: center;
    border: 1px solid rgba(255, 255, 255, 0.35);
    border-radius: 999px;
    color: #dcecff;
    font-size: 12px;
    font-weight: 600;
    padding: 7px 11px;
    background: rgba(255, 255, 255, 0.08);
}

@media (max-width: 991px) {
    .faq-one--home .faq-one__left {
        margin-right: 0;
        margin-bottom: 24px;
    }

    .faq-one--home .faq-one__right .accrodion-grp[data-faq-panel] {
        width: 100%;
    }

    .faq-one--home {
        padding: 56px 0 48px;
    }

}

/*--------------------------------------------------------------
# Industry Fit
--------------------------------------------------------------*/
.industry-fit {
    position: relative;
    display: block;
    padding: 0 0 34px;
}

.industry-fit .section-title-two {
    margin-bottom: 30px;
}

.industry-fit .row {
    row-gap: 14px;
}

.industry-fit__card {
    position: relative;
    overflow: hidden;
    border: 1px solid #d6e5fb;
    border-radius: 14px;
    background: linear-gradient(180deg, #ffffff 0%, #f6faff 100%);
    padding: 20px;
    min-height: 172px;
    box-shadow: 0 10px 22px rgba(16, 57, 117, 0.07);
    transition: transform 0.28s ease, box-shadow 0.28s ease, border-color 0.28s ease;
}

.industry-fit__card::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 4px;
    background: linear-gradient(90deg, #2081db 0%, #5dc9ff 100%);
}

.industry-fit__card:hover {
    transform: translateY(-4px);
    border-color: #bad2f4;
    box-shadow: 0 14px 30px rgba(16, 57, 117, 0.12);
}

.industry-fit__card h3 {
    margin: 0 0 8px;
    font-size: 24px;
}

.industry-fit__card h3 a {
    color: inherit;
}

.industry-fit__card h3 a:hover {
    color: #1f77d0;
}

.industry-fit__card p {
    margin: 0;
    color: #4f6483;
}

/*--------------------------------------------------------------
# Results Strip
--------------------------------------------------------------*/
