    display: grid;
    gap: 8px;
}

.client-portal-discovery__points li {
    display: flex;
    align-items: flex-start;
    gap: 9px;
    color: #1b2f4f;
}

.client-portal-discovery__points li .icon-check {
    margin-top: 5px;
    color: #1a7ad5;
}

.client-portal-discovery__cta {
    display: grid;
    gap: 10px;
}

.client-portal-discovery__cta .thm-btn {
