}

.results-strip__inner {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
}

.results-strip__item {
    border: 1px solid #d9e7fd;
    border-radius: 14px;
    background: linear-gradient(180deg, #fff 0%, #f4f8ff 100%);
    padding: 20px;
}

.results-strip__item h3 {
    margin: 0 0 7px;
    color: #0f3f84;
    font-size: 32px;
}

.results-strip__item p {
    margin: 0;
    font-size: 15px;
}

