.meeting-scheduler__timezone {
    margin: 12px 0 14px;
    font-size: 14px;
    color: #1a4d90;
    font-weight: 600;
}

.meeting-scheduler__timezone .icon-check {
    margin-right: 6px;
}

.cost-estimator__instant {
    margin-top: 22px;
    border: 1px solid #d8e6fb;
