    }

    .cost-estimator__instant-grid {
        grid-template-columns: 1fr;
    }

    .cost-estimator__form-actions {
        align-items: stretch;
    }

    .cost-estimator__btn {
        width: 100%;
        justify-content: center;
    }

    .sticky-quick-actions {
        display: none;
    }
