/*--------------------------------------------------------------
# Audit Lead
--------------------------------------------------------------*/
.audit-lead {
    position: relative;
    display: block;
    padding: 0 0 84px;
}

.audit-lead__inner {
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(120deg, #0f2f64 0%, #17458f 56%, #1b62c0 100%);
    padding: 44px;
}

.audit-lead__content {
    padding-right: 18px;
}

.audit-lead__content .section-title-two__tagline,
.audit-lead__content .section-title-two__title,
.audit-lead__text,
.audit-lead__meta span {
    color: var(--finris-white);
}

.audit-lead__text {
    margin: 10px 0 18px;
    color: rgba(255, 255, 255, 0.88);
}

.audit-lead__points {
    display: grid;
    gap: 10px;
}

.audit-lead__points li {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    color: rgba(255, 255, 255, 0.94);
    font-size: 16px;
}

.audit-lead__points li .icon-check {
    color: #5dd9ff;
    margin-top: 5px;
}

.audit-lead__meta {
    display: grid;
    gap: 8px;
    margin-top: 18px;
    font-size: 14px;
}

.audit-lead__meta strong {
    color: #86ddff;
}

.audit-lead__form-box {
    background: rgba(255, 255, 255, 0.94);
    border-radius: 16px;
    padding: 24px;
}

.audit-lead__input {
    margin-bottom: 14px;
}

.audit-lead__input input[type="text"],
.audit-lead__input input[type="email"],
.audit-lead__input select {
    width: 100%;
    height: 52px;
    border: 1px solid var(--finris-bdr-color);
    border-radius: 10px;
    background: #fff;
    padding: 0 15px;
    font-size: 15px;
    color: var(--finris-black);
    outline: none;
}

.audit-lead__input textarea {
    width: 100%;
    min-height: 120px;
    border: 1px solid var(--finris-bdr-color);
    border-radius: 10px;
    background: #fff;
    padding: 12px 15px;
    font-size: 15px;
    color: var(--finris-black);
    outline: none;
    resize: vertical;
}

.audit-lead__btn {
    border: none;
    background-color: #0f63b8;
    color: #fff;
}

@media (max-width: 1199px) {
    .audit-lead {
        padding-bottom: 74px;
    }

    .audit-lead__inner {
        padding: 30px;
    }

    .audit-lead__content {
        padding-right: 0;
        margin-bottom: 26px;
    }
}

@media (max-width: 767px) {
    .audit-lead {
        padding-bottom: 56px;
    }

    .audit-lead__inner {
        padding: 20px;
    }

    .audit-lead__form-box {
        padding: 16px;
    }
}








