.site-chat{position:fixed;right:22px;bottom:22px;z-index:120}
.ars-chat-robot-wrap{position:relative;display:inline-flex;align-items:center}
.ars-chat-pulse{position:absolute;inset:0;border-radius:999px;background:rgba(29,147,255,.38);pointer-events:none;animation:bot-pulse 2.6s ease-out infinite}
.ars-chat-pulse--2{animation-delay:1.3s}
.ars-chat-bubble{position:absolute;right:calc(100% + 14px);bottom:50%;transform:translateY(50%) translateX(6px) scale(.85);background:#fff;color:#0f1e35;font-size:13px;font-weight:700;font-family:Arial,sans-serif;white-space:nowrap;padding:9px 16px;border-radius:22px 22px 4px 22px;box-shadow:0 6px 24px rgba(0,0,0,.16);pointer-events:none;opacity:0;transition:opacity .3s,transform .3s}
.ars-chat-bubble::after{content:'';position:absolute;right:-8px;bottom:3px;border:8px solid transparent;border-left-color:#fff;border-right-width:0}
.ars-chat-bubble.ars-bubble-vis{opacity:1;transform:translateY(50%) translateX(0) scale(1)}
.ars-chat-robot-btn{animation:bot-walkin .9s cubic-bezier(.34,1.56,.64,1) both;cursor:pointer;position:relative;z-index:1;overflow:visible;min-height:64px;padding:0 18px 0 10px}
.ars-bot{width:42px;display:flex;flex-direction:column;align-items:center;position:relative;flex-shrink:0;margin-right:4px}
.ars-bot__antenna{display:flex;flex-direction:column;align-items:center}
.ars-bot__antenna-stem{width:2px;height:7px;background:rgba(255,255,255,.75);border-radius:1px}
.ars-bot__antenna-ball{width:8px;height:8px;border-radius:50%;background:#38bdf8;box-shadow:0 0 8px #38bdf8;margin-top:-1px;animation:bot-antenna 1.4s ease-in-out infinite}
.ars-bot__head{width:36px;height:26px;background:rgba(255,255,255,.96);border-radius:8px;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:3px 0;margin-top:1px}
.ars-bot__ear{position:absolute;width:5px;height:9px;background:rgba(255,255,255,.85);border-radius:3px;top:50%;transform:translateY(-50%)}
.ars-bot__ear--l{left:-6px}
.ars-bot__ear--r{right:-6px}
.ars-bot__eyes{display:flex;gap:7px}
.ars-bot__eye{width:9px;height:9px;background:#1d93ff;border-radius:50%;position:relative;overflow:hidden;animation:bot-blink 3.5s ease-in-out infinite}
.ars-bot__eye--r{animation-delay:.12s}
.ars-bot__pupil{position:absolute;top:2px;left:2px;width:3px;height:3px;background:#fff;border-radius:50%}
.ars-bot__mouth{width:16px;height:5px;border:2px solid #1d4ed8;border-top:none;border-radius:0 0 8px 8px}
.ars-bot__neck{width:8px;height:4px;background:rgba(255,255,255,.55);border-radius:2px}
.ars-bot__body{width:32px;height:20px;background:rgba(255,255,255,.88);border-radius:7px;position:relative;display:flex;align-items:center;justify-content:center}
.ars-bot__arm{position:absolute;width:8px;height:16px;background:rgba(255,255,255,.8);border-radius:4px;top:1px;transform-origin:top center}
.ars-bot__arm--l{left:-10px}
.ars-bot__arm--r{right:-10px}
.ars-bot__chest-light{width:9px;height:9px;border-radius:50%;background:#38bdf8;box-shadow:0 0 7px #38bdf8;animation:bot-chest 1.3s ease-in-out infinite}
.ars-bot__legs{display:flex;gap:6px;margin-top:2px}
.ars-bot__leg{width:10px;height:13px;background:rgba(255,255,255,.8);border-radius:3px 3px 5px 5px;transform-origin:top center}
.ars-bot__shadow{width:28px;height:5px;background:rgba(0,0,0,.18);border-radius:50%;margin-top:2px;animation:bot-shadow 2s ease-in-out infinite}
.ars-bot__zzz{display:none;position:absolute;top:-6px;right:-4px;font-size:11px;font-weight:800;color:#38bdf8;line-height:1;pointer-events:none}
.ars-bot__zzz span{display:inline-block}
.ars-bot__zzz span:nth-child(1){animation:bot-zzz 2s ease-in-out .5s infinite}
.ars-bot__zzz span:nth-child(2){animation:bot-zzz 2s ease-in-out 1s infinite}
.ars-bot.s-idle{animation:s-idle 2.6s ease-in-out infinite}
.ars-bot.s-walk{animation:s-walk-body .5s ease-in-out infinite}
.ars-bot.s-walk .ars-bot__leg--l{animation:s-walk-leg-l .5s ease-in-out infinite}
.ars-bot.s-walk .ars-bot__leg--r{animation:s-walk-leg-r .5s ease-in-out infinite}
.ars-bot.s-walk .ars-bot__arm--l{animation:s-walk-arm-l .5s ease-in-out infinite}
.ars-bot.s-walk .ars-bot__arm--r{animation:s-walk-arm-r .5s ease-in-out infinite}
.ars-bot.s-jump{animation:s-jump .65s cubic-bezier(.5,2,.5,.8) infinite}
.ars-bot.s-jump .ars-bot__leg--l,.ars-bot.s-jump .ars-bot__leg--r{animation:s-jump-legs .65s ease-in-out infinite}
.ars-bot.s-wave{animation:s-idle 2s ease-in-out infinite}
.ars-bot.s-wave .ars-bot__arm--r{animation:s-wave-arm .45s ease-in-out infinite}
.ars-bot.s-dance{animation:s-dance-body .4s ease-in-out infinite}
.ars-bot.s-dance .ars-bot__arm--l{animation:s-dance-al .4s ease-in-out infinite}
.ars-bot.s-dance .ars-bot__arm--r{animation:s-dance-ar .4s ease-in-out infinite}
.ars-bot.s-dance .ars-bot__leg--l{animation:s-walk-leg-l .4s ease-in-out infinite}
.ars-bot.s-dance .ars-bot__leg--r{animation:s-walk-leg-r .4s ease-in-out infinite}
.ars-bot.s-spin{animation:s-spin .9s linear infinite}
.ars-bot.s-excited{animation:s-excited .22s ease-in-out infinite}
.ars-bot.s-excited .ars-bot__arm--l{animation:s-flail-l .18s ease-in-out infinite}
.ars-bot.s-excited .ars-bot__arm--r{animation:s-flail-r .18s ease-in-out infinite .09s}
.ars-bot.s-celebrate{animation:s-cel-body .55s ease-in-out infinite}
.ars-bot.s-celebrate .ars-bot__arm--l{animation:s-cel-arm-l .55s ease-in-out infinite}
.ars-bot.s-celebrate .ars-bot__arm--r{animation:s-cel-arm-r .55s ease-in-out infinite}
.ars-bot.s-flip{animation:s-flip 1.1s cubic-bezier(.5,2,.5,.8) infinite}
.ars-bot.s-think{animation:s-think-body 2s ease-in-out infinite}
.ars-bot.s-think .ars-bot__arm--r{animation:s-think-ar 2s ease-in-out infinite}
.ars-bot.s-stretch{animation:s-stretch-b 1.6s ease-in-out infinite}
.ars-bot.s-stretch .ars-bot__arm--l{animation:s-stretch-al 1.6s ease-in-out infinite}
.ars-bot.s-stretch .ars-bot__arm--r{animation:s-stretch-ar 1.6s ease-in-out infinite}
.ars-bot.s-bow .ars-bot__head{animation:s-bow-body 2.2s ease-in-out infinite;transform-origin:bottom center}
.ars-bot.s-look{animation:s-idle 3s ease-in-out infinite}
.ars-bot.s-look .ars-bot__head{animation:s-look-head 2.2s ease-in-out infinite}
.ars-bot.s-disco{animation:s-disco-body .4s ease-in-out infinite}
.ars-bot.s-disco .ars-bot__leg--l{animation:s-walk-leg-l .4s ease-in-out infinite}
.ars-bot.s-disco .ars-bot__leg--r{animation:s-walk-leg-r .4s ease-in-out infinite}
.ars-bot.s-power{animation:s-power .15s ease-in-out infinite}
.ars-bot.s-power .ars-bot__head,.ars-bot.s-power .ars-bot__body{box-shadow:0 0 14px rgba(56,189,248,.9)}
.ars-bot.s-sleep{animation:s-sleep-body 2.8s ease-in-out infinite}
.ars-bot.s-sleep .ars-bot__zzz{display:block}
.ars-bot.s-point{animation:s-idle 2s ease-in-out infinite}
.ars-bot.s-point .ars-bot__arm--r{animation:s-point-ar 2s ease-in-out infinite}
.ars-bot.s-shrink{animation:s-shrink 1.2s ease-in-out infinite}
.site-chat--open .ars-chat-pulse,.site-chat--open .ars-chat-bubble{display:none}

.site-chat__toggle {
    border: 0;
    border-radius: 999px;
    min-height: 58px;
    padding: 0 20px 0 16px;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    background: linear-gradient(135deg, #0f63b8 0%, #268be2 100%);
    color: #fff;
    box-shadow: 0 18px 34px rgba(15, 99, 184, 0.28);
    font-size: 15px;
    font-weight: 700;
}

.site-chat--open .site-chat__toggle {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
}

.site-chat__toggle-icon {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255,255,255,.18);
}

.site-chat__panel {
    width: min(380px, calc(100vw - 24px));
    margin-top: 12px;
    margin-left: auto;
    border-radius: 24px;
    overflow: hidden;
    background: linear-gradient(180deg, #ffffff 0%, #f6faff 100%);
    border: 1px solid rgba(193, 215, 244, 0.96);
    box-shadow: 0 24px 52px rgba(14, 53, 111, 0.18);
    position: relative;
}

.site-chat__panel::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.28);
    pointer-events: none;
}

.site-chat__head {
    display: flex;
    justify-content: space-between;
    gap: 14px;
    align-items: center;
    padding: 16px 18px;
    background: linear-gradient(135deg, #10356b 0%, #166fc4 100%);
    color: #fff;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.site-chat__brand {
    display: flex;
    align-items: center;
    gap: 10px;
}

.site-chat__back {
    width: 36px;
    height: 36px;
    border: 0;
    border-radius: 50%;
    background: rgba(255,255,255,.16);
    color: #fff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    line-height: 1;
    flex: 0 0 36px;
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.08);
}

.site-chat__back[hidden] {
    display: none !important;
}

.site-chat__brand-logo,
.site-chat__powered-logo {
    width: 36px;
    height: 36px;
    border-radius: 12px;
    display: block;
    object-fit: contain;
    background: rgba(255,255,255,.14);
    padding: 4px;
    flex: 0 0 36px;
}

.site-chat__brand strong,
.site-chat__brand span {
    display: block;
}

.site-chat__brand strong {
    font-size: 15px;
    line-height: 1.2;
}

.site-chat__brand span {
    font-size: 12px;
    opacity: .84;
}

.site-chat__close {
    width: 36px;
    height: 36px;
    border: 0;
    border-radius: 50%;
    background: rgba(255,255,255,.14);
    color: #fff;
    font-size: 28px;
    line-height: 1;
}

.site-chat__body {
    padding: 16px;
}

.site-chat__body--compact .site-chat__messages:empty {
    display: none;
}

.site-chat__messages {
    display: grid;
    gap: 10px;
    max-height: 280px;
    overflow: auto;
    padding-right: 8px;
    margin-right: -2px;
    margin-bottom: 2px;
    scrollbar-width: thin;
    scrollbar-color: #c8d7ef transparent;
}

.site-chat__messages::-webkit-scrollbar {
    width: 6px;
}

.site-chat__messages::-webkit-scrollbar-track {
    background: transparent;
}

.site-chat__messages::-webkit-scrollbar-thumb {
    background: #c8d7ef;
    border-radius: 999px;
}

.site-chat__bubble {
    max-width: 88%;
    border-radius: 18px;
    padding: 12px 14px;
    font-size: 14px;
    line-height: 1.65;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.site-chat__bubble--system {
    background: #edf6ff;
    color: #123b76;
}

.site-chat__bubble--visitor {
    background: #10356b;
    color: #fff;
    margin-left: auto;
}

.site-chat__bubble--admin {
    background: #ffffff;
    border: 1px solid #dbe7f9;
    color: #173153;
}

.site-chat__typing {
    display: inline-flex;
    gap: 5px;
    align-items: center;
    padding: 12px 14px;
    border-radius: 18px;
    background: #edf6ff;
    width: fit-content;
}

.site-chat__typing span {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #5e83b5;
    animation: siteChatTyping 1.1s infinite ease-in-out;
}

.site-chat__typing span:nth-child(2) { animation-delay: .15s; }
.site-chat__typing span:nth-child(3) { animation-delay: .3s; }

@keyframes siteChatTyping {
    0%, 80%, 100% { transform: scale(.6); opacity: .5; }
    40% { transform: scale(1); opacity: 1; }
}

.site-chat__attachment {
    display: block;
    margin-top: 10px;
    max-width: 100%;
    border-radius: 14px;
}

.site-chat__attachment-link {
    display: block;
    margin-top: 10px;
    cursor: zoom-in;
}

.site-chat__image-modal {
    position: absolute;
    inset: 0;
    z-index: 30;
}

.site-chat__image-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(8, 25, 56, 0.72);
    backdrop-filter: blur(2px);
}

.site-chat__image-dialog {
    position: absolute;
    inset: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 20px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.04);
    box-shadow: 0 24px 48px rgba(6, 22, 54, 0.28);
}

.site-chat__image-close {
    position: absolute;
    top: 12px;
    right: 12px;
    width: 38px;
    height: 38px;
    border: 0;
    border-radius: 50%;
    background: rgba(15, 99, 184, 0.92);
    color: #fff;
    font-size: 26px;
    line-height: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    z-index: 1;
